/**
 * Lucide 官方 SVG 图标库 — 全部使用标准 24×24 线框风格
 * https://lucide.dev
 */

// 纯路径图标辅助函数
function svg(paths: string[], size = 16, sw = 2): string {
  const p = paths.map((d) => `<path d="${d}"/>`).join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`;
}

// 资源图标辅助函数：直接内联 src/assets 下的 SVG（使用 currentColor 继承文字色，viewBox 默认 14×14）
function assetSvg(inner: string, size = 16, viewBox = "0 0 14 14"): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="${viewBox}" fill="none">${inner}</svg>`;
}

